export const DELETE = Symbol('delete');

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

export function cloneValue(value) {
  if (value === undefined || value === DELETE) throw new TypeError();
  if (value === null || typeof value === 'boolean' || typeof value === 'string') return value;
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError();
    return value;
  }
  if (typeof value === 'function' || typeof value === 'symbol') throw new TypeError();
  if (Array.isArray(value)) {
    const out = [];
    for (const item of value) {
      if (item === undefined || item === DELETE) throw new TypeError();
      out.push(cloneValue(item));
    }
    return out;
  }
  if (!isPlainObject(value)) throw new TypeError();
  const out = {};
  for (const key of Object.keys(value)) {
    const prop = value[key];
    if (prop === undefined || prop === DELETE) continue;
    out[key] = cloneValue(prop);
  }
  return out;
}

