import { cloneValue, DELETE } from './clone-value.mjs';

export { DELETE };

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function validateLayerValue(value, inArray) {
  if (!inArray && (value === undefined || value === DELETE)) return;
  if (inArray && (value === undefined || value === DELETE)) throw new TypeError();
  if (value === null || typeof value === 'boolean' || typeof value === 'string') return;
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError();
    return;
  }
  if (typeof value === 'function' || typeof value === 'symbol') throw new TypeError();
  if (Array.isArray(value)) {
    for (const item of value) validateLayerValue(item, true);
    return;
  }
  if (!isPlainObject(value)) throw new TypeError();
  for (const key of Object.keys(value)) validateLayerValue(value[key], false);
}

function validateLayer(layer) {
  for (const key of Object.keys(layer)) validateLayerValue(layer[key], false);
}

function mergeInto(target, layer) {
  for (const key of Object.keys(layer)) {
    const incoming = layer[key];
    if (incoming === undefined) continue;
    if (incoming === DELETE) {
      delete target[key];
      continue;
    }
    const previous = target[key];
    if (isPlainObject(previous) && isPlainObject(incoming)) {
      mergeInto(previous, incoming);
      continue;
    }
    target[key] = cloneValue(incoming);
  }
}

export function mergeLayers(...layers) {
  const out = {};
  for (const layer of layers) {
    if (layer === undefined) continue;
    if (!isPlainObject(layer)) throw new TypeError();
    validateLayer(layer);
    mergeInto(out, layer);
  }
  return out;
}

